From c778a514032474a7e9d88abfb9945946bed36eac Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 11:09:39 +0100
Subject: [PATCH] Positioner: place new items before they are first shown

New and dropped files got the first free cell and were moved to the
click or drop position by a queued call, so a frame could show them in
the corner. The positioner now does those moves right after inserting.

BUG: 499976
---
 .../desktop/plugins/folder/foldermodel.cpp    | 19 ++++++++++++-------
 .../desktop/plugins/folder/foldermodel.h      |  3 +++
 .../desktop/plugins/folder/positioner.cpp     |  2 ++
 3 files changed, 17 insertions(+), 7 deletions(-)

diff --git a/containments/desktop/plugins/folder/foldermodel.cpp b/containments/desktop/plugins/folder/foldermodel.cpp
index 678bae687c..16f567df49 100644
--- a/containments/desktop/plugins/folder/foldermodel.cpp
+++ b/containments/desktop/plugins/folder/foldermodel.cpp
@@ -280,18 +280,15 @@ FolderModel::FolderModel(QObject *parent)
             const auto url = itemForIndex(idx).url();
             auto it = m_dropTargetPositions.find(url.fileName());
             if (it != m_dropTargetPositions.end()) {
-                const auto pos = it.value();
+                m_pendingMoves.append({it.value(), url});
                 m_dropTargetPositions.erase(it);

                 // Deferred to allow proxies of this to also handle the rowsInserted
                 // we're dealing with URLs here so it's safe to defer here
                 // See BUG:481254
-                QMetaObject::invokeMethod(
-                    this,
-                    [this, pos, url]() {
-                        Q_EMIT move(pos.x(), pos.y(), {url});
-                    },
-                    Qt::QueuedConnection);
+                // The positioner flushes them as soon as it's done, so the item
+                // is never shown at a temporary position.
+                QMetaObject::invokeMethod(this, &FolderModel::flushPendingMoves, Qt::QueuedConnection);
             }
         }
     });
@@ -385,6 +382,14 @@ void FolderModel::invalidateFilterIfComplete()
     invalidateFilter();
 }

+void FolderModel::flushPendingMoves()
+{
+    const auto moves = std::exchange(m_pendingMoves, {});
+    for (const auto &[pos, url] : moves) {
+        Q_EMIT move(pos.x(), pos.y(), {url});
+    }
+}
+
 void FolderModel::newFileMenuItemCreationStarted(const QUrl &url)
 {
     Q_UNUSED(url);
diff --git a/containments/desktop/plugins/folder/foldermodel.h b/containments/desktop/plugins/folder/foldermodel.h
index c2a2a388f9..1179747293 100644
--- a/containments/desktop/plugins/folder/foldermodel.h
+++ b/containments/desktop/plugins/folder/foldermodel.h
@@ -254,6 +254,8 @@ public:

     Q_INVOKABLE bool isBlank(int row) const;

+    void flushPendingMoves();
+
     Q_INVOKABLE QAction *action(const QString &name) const;
     QObject *newMenu() const;
     Q_INVOKABLE void updateActions();
@@ -383,6 +385,7 @@ private:
     // is not using the URL to easily support desktop:/ URL schemes
     QHash<QString, QPoint> m_dropTargetPositions;
     QTimer *m_dropTargetPositionsCleanup;
+    QList<std::pair<QPoint, QUrl>> m_pendingMoves;
     QPointer<KFilePreviewGenerator> m_previewGenerator;
     QPointer<KAbstractViewAdapter> m_viewAdapter;
     KActionCollection m_actionCollection;
diff --git a/containments/desktop/plugins/folder/positioner.cpp b/containments/desktop/plugins/folder/positioner.cpp
index 8fc7ec4c6c..8b5bb9df09 100644
--- a/containments/desktop/plugins/folder/positioner.cpp
+++ b/containments/desktop/plugins/folder/positioner.cpp
@@ -775,6 +775,8 @@ void Positioner::sourceRowsInserted(const QModelIndex &parent, int first, int la
             maybeRestoreAndApplyChangedPositions(false);
         }
     }
+
+    m_folderModel->flushPendingMoves();
 }

 void Positioner::sourceRowsMoved(const QModelIndex &sourceParent, int sourceStart, int sourceEnd, const QModelIndex &destinationParent, int destinationRow)
